Mesh sphereMesh(unsigned segments,double radius){Mesh mesh;unsigned rings=segments/2-1;mesh.vertices.push_back({0,0,radius});for(unsigned ring=1;ring<=rings;++ring){double phi=3.141592653589793*ring/(rings+1);for(unsigned i=0;i<segments;++i){double theta=6.283185307179586*i/segments;mesh.vertices.push_back({radius*std::sin(phi)*std::cos(theta),radius*std::sin(phi)*std::sin(theta),radius*std::cos(phi)});}}unsigned bottom=unsigned(mesh.vertices.size());mesh.vertices.push_back({0,0,-radius});for(unsigned i=0;i<segments;++i){unsigned next=(i+1)%segments;mesh.faces.push_back({0,1+i,1+next});for(unsigned ring=0;ring+1<rings;++ring){unsigned a=1+ring*segments+i,b=1+ring*segments+next,c=a+segments,d=b+segments;mesh.faces.push_back({a,c,b});mesh.faces.push_back({b,c,d});}mesh.faces.push_back({bottom,1+(rings-1)*segments+next,1+(rings-1)*segments+i});}return mesh;}
